}

.mastered-from-desc {
  font-size: 10px;
  color: var(--text-dim);
}

.mastered-arrow {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--sig-color);
  animation: signature-title-in 0.5s ease-out 0.35s both;
}

