  flex-direction: column;
  align-items: center;
  flex: none;
}

.rite-hero {
  position: relative;
  width: 96px;
  height: 96px;
}

/* The fire under the hero, in the leaning Class's colour. */
.rite-pool {
  position: absolute;
  left: 50%;
  bottom: -6px;
  width: 132px;
  height: 30px;
  margin-left: -66px;
  border-radius: 50%;
  background: radial-gradient(ellipse, color-mix(in srgb, var(--rite-color) 75%, #fff 10%), color-mix(in srgb, var(--rite-color) 30%, transparent) 45%, transparent 72%);
