  animation: rite-pool 2.6s ease-in-out infinite;
  transition: background 0.5s var(--ease-out);
}

@keyframes rite-pool {
  0%,
  100% {
    opacity: 0.85;
    transform: scaleX(1);
  }
  50% {
    opacity: 1;
    transform: scaleX(1.08);
  }
}

.rite-portrait {
  position: relative;
  width: 96px;
  height: 96px;
  image-rendering: pixelated;
  filter: drop-shadow(0 -4px 10px color-mix(in srgb, var(--rite-color) 45%, transparent)) drop-shadow(0 2px 3px rgba(0, 0, 0, 0.7));
  transform-origin: center bottom;
  animation: hero-idle-breath 3.1s ease-in-out infinite;
}

/* The picked Class's mark, risen off the hero's shoulder. */
.rite-mark {
  position: absolute;
  right: -18px;
  top: 4px;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  color: var(--rite-color);
  background: url('../../art/ui/medallion.png') 0 0 / 30px 30px no-repeat;
  image-rendering: pixelated;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--rite-color) 70%, transparent));
  animation: rite-mark-in 0.35s var(--ease-spring) both;
}

.rite-mark > svg {
