  filter: drop-shadow(0 0 3px var(--rite-color));
}

@keyframes rite-mark-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.6);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.rite-eyebrow {
  margin-top: 10px;
  color: var(--rite-ink);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.28em;
  text-transform: uppercase;
}

.rite-name {
  margin: 2px 0 0;
  font-size: 22px;
  font-weight: 800;
  color: var(--rite-title);
  text-shadow: 0 0 10px var(--rite-glow), 0 0 22px var(--rite-glow-far);
}

.rite-types {
  display: flex;
  gap: 8px;
  margin-top: 2px;
}

.verb-card-list {
  position: relative;
  z-index: 1;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
}

/* One height for all three, so they read as a set on offer rather than a list. */
.verb-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  height: 112px;
  padding: 8px 12px 8px 10px;
  border: 4px solid transparent;
  border-image: url('../../art/ui/slot-thin.png') 2 / 4px round;
  background:
    linear-gradient(100deg, color-mix(in srgb, var(--rite-color) 16%, transparent), transparent 55%) padding-box,
    var(--rite-card) padding-box;
  box-shadow: inset 0 2px 0 color-mix(in srgb, var(--rite-color) 45%, transparent);
  image-rendering: pixelated;
  cursor: pointer;
  transition: transform var(--dur-mid) var(--ease-spring), opacity var(--dur-mid) var(--ease-out), box-shadow var(--dur-mid) var(--ease-out);
}

.verb-card:active {
  transform: scale(0.985);
}

.verb-card.is-picked {
  border-image-source: url('../../art/ui/slot-thin-lit.png');
  background:
    linear-gradient(100deg, color-mix(in srgb, var(--rite-color) 30%, transparent), transparent 70%) padding-box,
    var(--rite-card-lit) padding-box;
  box-shadow:
    inset 0 2px 0 var(--rite-color),
    0 0 18px -4px color-mix(in srgb, var(--rite-color) 70%, transparent);
}

.verb-card.is-dimmed {
  opacity: 0.55;
}

.verb-card-socket {
  flex: none;
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  color: var(--rite-color);
  background:
    radial-gradient(circle, color-mix(in srgb, var(--rite-color) 35%, transparent), transparent 46%),
    url('../../art/ui/medallion.png') 0 0 / 48px 48px no-repeat;
  image-rendering: pixelated;
  filter: drop-shadow(0 3px 5px rgba(0, 0, 0, 0.6));
}

.verb-card.is-picked .verb-card-socket {
  filter: drop-shadow(0 3px 5px rgba(0, 0, 0, 0.6)) drop-shadow(0 0 8px color-mix(in srgb, var(--rite-color) 80%, transparent));
}

.verb-card-glyph {
  width: 22px;
  height: 22px;
}

.verb-card-body {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.verb-card-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.verb-card-name {
  font-size: 17px;
  font-weight: 800;
  color: var(--text);
}

.verb-card.is-picked .verb-card-name {
  color: var(--rite-title);
}

.verb-card-kind {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--rite-color) 80%, var(--text-dim));
}

.verb-card-verb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}

.verb-card-verb-name {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 800;
}

.verb-card-verb-name > svg {
  width: 12px;
  height: 12px;
}

.verb-card-fact {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
}

.verb-card-fact.is-mana {
  color: var(--mana, #6cb6ff);
}

.verb-card-desc {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-size: 11px;
  line-height: 1.35;
  color: var(--text-dim);
}

/* A Class card (AcademyNodeScreen ClassCard): the mark and name over the verb drawn as the fight draws it —
   the move button, or the innate readout — so a move reads as a move and a passive as a passive. */
.verb-card.class-card {
  height: auto;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  padding: 8px 10px 10px;
}

.academy-class-list {
  overflow-y: auto;
  justify-content: safe center;
}

/* The Academy's landing: who can still learn a Class, under the three on offer. A free hero is
   lit; one already schooled is dimmed and wears its Class's mark. 48px figures at 1x. */
.academy-students-label {
  position: relative;
  z-index: 1;
  margin-top: 10px;
  text-align: center;
}

.academy-students {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: center;
  gap: 4px;
  margin: 4px 0 12px;
}

.academy-student {
  position: relative;
  width: 48px;
  height: 48px;
}

.academy-student-portrait {
  width: 48px;
  height: 48px;
  image-rendering: pixelated;
  filter: drop-shadow(0 0 6px var(--rite-glow)) drop-shadow(0 2px 2px rgba(0, 0, 0, 0.7));
}

.academy-student.has-class .academy-student-portrait {
  filter: grayscale(0.85) brightness(0.55) drop-shadow(0 2px 2px rgba(0, 0, 0, 0.7));
}

.academy-student-mark {
  position: absolute;
  right: -2px;
  bottom: -2px;
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid currentColor;
  background: rgba(10, 11, 15, 0.9);
}

.academy-student-mark .status-glyph {
  width: 12px;
  height: 12px;
}

/* The hero step: the Class being taught, and the way back to the three. */
.academy-heroes-head {
  position: relative;
  z-index: 1;
  margin-bottom: 6px;
}

.academy-teaching {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 18px;
  font-weight: 800;
}

.academy-teaching .status-glyph {
  width: 20px;
  height: 20px;
}

.academy-ask {
  position: relative;
  z-index: 1;
  margin-bottom: 8px;
}

.class-card-head {
  align-items: center;
  justify-content: flex-start;
}

.class-card-mark {
  display: inline-flex;
  color: var(--rite-color);
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--rite-color) 60%, transparent));
}

.class-card-mark .status-glyph {
  width: 18px;
  height: 18px;
}

.class-card-verb {
  display: flex;
  flex-direction: column;
  pointer-events: none;
}

.class-card-verb .passive-readout {
  background: rgba(10, 12, 18, 0.55);
}

.rite-screen .resolve-button {
  position: relative;
  z-index: 1;
}

/* The reveal: the same hero at the same rim, a flare out of the fire, the Class named in its colour
   and the verb it now carries read whole below. */
.rite-reveal {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100%;
  padding: 24px 0 12px;
  text-align: center;
}

.rite-reveal-flash {
  position: absolute;
  left: 50%;
  top: 0;
  width: 360px;
  height: 300px;
  margin-left: -180px;
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(255, 240, 200, 0.85), color-mix(in srgb, var(--rite-color) 45%, transparent) 35%, transparent 68%);
  opacity: 0;
  pointer-events: none;
  animation: rite-flare 1.1s var(--ease-out) both;
}

.rite-mark.is-reveal {
  right: -22px;
  top: -4px;
  width: 40px;
  height: 40px;
  background-size: 40px 40px;
  animation: rite-mark-in 0.5s var(--ease-spring) 0.35s both;
}

.rite-mark.is-reveal > svg {
  width: 20px;
  height: 20px;
}

.rite-reveal-name {
  margin-top: 4px;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--rite-color);
  text-shadow: 0 0 12px color-mix(in srgb, var(--rite-color) 60%, transparent);
  animation: title-tagline-fade 0.5s ease 0.45s both;
}

.rite-reveal-verb {
  width: 100%;
  margin-top: 16px;
  text-align: left;
  animation: rite-step-up 0.6s var(--ease-out) 0.6s both;
}

.rite-reveal-verb > * {
  width: 100%;
}

/* A move's sheet is drawn bare (it usually sits in a window); here it is carved in like the cards. */
.rite-reveal-verb > .passive-readout {
  border-image-source: url('../../art/ui/slot-thin-lit.png');
  background:
    linear-gradient(100deg, color-mix(in srgb, var(--rite-color) 18%, transparent), transparent 60%) padding-box,
    var(--rite-card) padding-box;
}

.rite-reveal-verb.is-move {
  padding: 10px 12px;
  border: 4px solid transparent;
  border-image: url('../../art/ui/slot-thin-lit.png') 2 / 4px round;
  background:
    linear-gradient(100deg, color-mix(in srgb, var(--rite-color) 18%, transparent), transparent 60%) padding-box,
    var(--rite-card) padding-box;
  image-rendering: pixelated;
}

@media (prefers-reduced-motion: reduce) {
  .rite-pool,
  .rite-portrait {
    animation: none;
  }
}

/* --- The node dossier (NodeDossierOverlay.tsx) ------------------------- */
/* What a hold on a map node opens. It sits on the move dossier's chassis —
   identity stripe and disc in the node's own colour, sections on scored
   hairlines — and it is a LEDGER: a row per thing the node pays or costs,
   glyph, label, figure. It replaced a grey .log-panel carrying one sentence
   (2026-09-11, per user direction): the numbers were in the prose, and prose
   is read once where a column of figures is compared. A lane the node does
   not pay is still a row, dimmed to a dash, so the Elite-or-Battle fork reads
   as two columns of one table rather than two paragraphs. */
.node-dossier-panel {
  gap: 0;
  border-top-width: 3px;
  background:
    linear-gradient(155deg, color-mix(in srgb, var(--node-color) 16%, transparent), transparent 46%),
    var(--surface-raised);
}

.node-dossier-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* .move-detail-disc, lit from the node colour rather than from a type's rgb. */
.node-dossier-disc {
  width: 52px;
  height: 52px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: var(--node-color);
  background: radial-gradient(
    circle at 32% 28%,
    color-mix(in srgb, var(--node-color) 34%, transparent),
    color-mix(in srgb, var(--node-color) 10%, transparent)
  );
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--node-color) 40%, transparent),
    0 0 18px -6px var(--node-color);
}

.node-dossier-disc svg {
  width: 31px;
  height: 31px;
}

/* The tile's own pixel art in place of the glyph: bare, larger, crisp. */
.node-dossier-disc.has-art {
  width: 64px;
  height: 64px;
  border-radius: 0;
  background: none;
  box-shadow: none;
}

.node-dossier-disc.has-art img {
  width: 64px;
  height: 64px;
  object-fit: contain;
  image-rendering: pixelated;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.6));
}

.node-dossier-titles {
  flex: 1;
  min-width: 0;
}

.node-dossier-name {
  font-size: 19px;
  font-weight: 700;
  color: var(--text);
  line-height: 1.2;
}

.node-dossier-line {
  margin-top: 3px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.node-dossier-facts {
  display: flex;
  flex-direction: column;
  margin-top: 10px;
  border-top: 1px solid var(--border);
}

.node-dossier-fact {
  display: grid;
  grid-template-columns: 19px 1fr auto;
  align-items: center;
  column-gap: 9px;
  padding: 7px 0;
}

.node-dossier-fact + .node-dossier-fact {
  border-top: 1px solid color-mix(in srgb, var(--border) 55%, transparent);
}

.node-dossier-fact-glyph {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 19px;
  height: 19px;
  color: var(--node-color);
}

.node-dossier-fact-glyph svg {
  width: 17px;
  height: 17px;
  margin: 0;
}

.node-dossier-fact-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.node-dossier-fact-value {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  text-align: right;
}

.node-dossier-fact-value strong {
  font-size: 16px;
  font-weight: 800;
  line-height: 1.15;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.node-dossier-fact-note {
  font-size: 10px;
  line-height: 1.3;
  color: var(--text-dim);
}

/* The act's rarity odds as one bar: every tier in order, each as wide as its
   weight, in the tier colour every item box already wears. */
.node-dossier-odds {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: 2px;
  padding-top: 10px;
  border-top: 1px solid var(--border);
}

.node-dossier-odds-bar {
  display: flex;
  gap: 2px;
  height: 6px;
  border-radius: 3px;
  overflow: hidden;
}

.node-dossier-odds-seg {
  flex: 0 1 0;
  min-width: 3px;
  background: var(--rarity-color);
}

.node-dossier-odds-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.node-dossier-odds-key strong {
  font-size: 12px;
  color: var(--rarity-color);
  font-variant-numeric: tabular-nums;
}

/* --- The item dossier (ItemDossier.tsx) -------------------------------- */
/* What a hold on any item box opens, on the move dossier's chassis with the
   tier colour for the stripe, the wash and the disc. Three facets in the
   move card's order — identity, numbers, payload — and the payload is spelled
   out whole: every passive with its full description and its grant chips,
   every Elemental Force with its rule. It replaced the grey .move-info-panel
   that printed "Grants: Sunder" and left the player to find out what Sunder
   was (2026-09-11, per user direction). */
.item-detail-card {
  --move-type-rgb: var(--rarity-rgb);
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.item-detail-disc {
  position: relative;
  color: var(--rarity-color);
}

.item-detail-disc .equip-glyph {
  width: 30px;
  height: 30px;
  color: var(--rarity-color);
}

/* The enchant's element, on the disc's rim the way ItemPiece pins it to the chit's corner. */
.item-detail-enchant {
  position: absolute;
  right: -3px;
  bottom: -3px;
  width: 21px;
  height: 21px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--panel);
  box-shadow: 0 0 0 1px var(--border);
}

.item-detail-enchant svg {
  width: 13px;
  height: 13px;
}

/* The one figure about an item that is not on its face: what a Guild Hall pays for it. */
.item-detail-sell {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  align-self: flex-start;
  font-size: 13px;
  font-weight: 800;
