}

/* One merge: the partner, where it is, the mark, and the piece the pair becomes — cut in the
   tier it REACHES, since that tier is the whole reason to buy. */
.equip-buy-merge-row {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) 22px 38px auto;
  align-items: center;
  gap: 8px;
  padding: 6px 8px 6px 6px;
  border-radius: var(--radius-md);
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.02), color-mix(in srgb, var(--merge-color) 12%, transparent));
  border: 1px solid color-mix(in srgb, var(--merge-color) 30%, var(--border));
