}

.equip-buy-merge-piece.is-result {
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--merge-color) 70%, transparent));
}

.equip-buy-merge-text {
  display: flex;
  flex-direction: column;
  gap: 1px;
