  font-size: 10px;
  font-weight: 800;
  color: var(--text-dim);
}

.equip-buy-merge-where {
  font-size: 10px;
  color: var(--text-dim);
}

.equip-buy-merge-arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--merge-color);
}

.equip-buy-merge-arrow .merge-mark {
  width: 14px;
  height: 14px;
}

.equip-buy-merge-result {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--merge-color);
}

.equip-buy-footer {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--border);
}

/* The purse before and after, in the run's one gold chip language. */
.equip-buy-ledger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  align-self: center;
  padding: 3px 12px;
  border-radius: var(--radius-pill);
  background: rgba(224, 166, 60, 0.1);
  border: 1px solid rgba(224, 166, 60, 0.3);
  font-size: 12px;
  font-weight: 800;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.equip-buy-ledger .resource-glyph {
  width: 13px;
  height: 13px;
}

.equip-buy-ledger-now {
  color: var(--text-dim);
  font-weight: 700;
}

.equip-buy-ledger-arrow {
  color: var(--text-dim);
  font-weight: 400;
}

.equip-buy-ledger.is-short {
