  border-color: rgba(217, 84, 84, 0.35);
  color: var(--enemy, #d95454);
}

.equip-buy-button {
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 12px;
